{
  "claims": [
    {
      "claim": "The bill would replace every occurrence of “June 30” with “June 15” in Tennessee Code Annotated, Section 49-6-3507(c).",
      "summary_quote": "change the date “June 30” to “June 15” wherever it appears in Tennessee Code Annotated, Section 49-6-3507(c)",
      "verdict": "supported",
      "source_quote": "Tennessee Code Annotated, Section 49-6-3507(c), is amended by\n\ndeleting \"June 30\" wherever it appears and substituting \"June 15\".",
      "error_type": "none",
      "rationale": "Section 1 specifies the same dates, substitution, and statutory scope."
    },
    {
      "claim": "The bill concerns education freedom scholarships.",
      "summary_quote": "concerning education freedom scholarships",
      "verdict": "supported",
      "source_quote": "relative to education freedom scholarships.",
      "error_type": "none",
      "rationale": "The bill's title expressly identifies this subject."
    },
    {
      "claim": "The bill would take effect upon becoming law.",
      "summary_quote": "It would take effect upon becoming law.",
      "verdict": "supported",
      "source_quote": "This act takes effect upon becoming a law, the public welfare requiring it.",
      "error_type": "none",
      "rationale": "Section 2 expressly provides this effective date."
    }
  ]
}
